-- Запись журнала обновлений (ADR 0077): выпуск 57 — «Орг.техника» запоминает отборы списков.
--
-- Схему миграция не трогает вовсе: работа целиком во фронте, хранится набор в браузере
-- сотрудника — ни таблицы, ни столбца под него не заведено (ADR 0139).
--
-- Номер файла и `seq` взяты по факту: на 27.08.2026 последней миграцией была 0213, последним
-- выпуском — 56 (версия `0.1.47.0138`, справочник прицепов), отсюда файл 0214 и `seq = 57`.
-- Счётчик выпусков продолжает `0.1.48`, хвост версии — номер ADR решения (ADR 0139).
--
-- ПУНКТ ПРО ПАМЯТЬ ОТБОРОВ СТОИТ ПЕРВЫМ И НАЗЫВАЕТ ГРАНИЦЫ, а не только пользу. Человек, у
-- которого список открылся не с начала, должен из журнала понять три вещи: почему так, что это
-- его собственный вчерашний выбор и чем его снять. Отдельно сказано про поиск: он намеренно не
-- сохраняется, и это ровно тот случай, когда молчание читалось бы как непоследовательность.
--
-- ПУНКТ ПРО ОБЩИЙ КОМПЬЮТЕР обязателен: набор хранится в браузере, и вопрос «а увидит ли мой
-- срез сменщик» задают раньше, чем успевают спросить.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  57, '0.1.48.0139', '2026-08-27', 'Раздел «Орг.техника» запоминает, как вы смотрите на списки', '{139}',
  '[
    {"kind":"feature","text":"Отборы в разделе «Орг.техника» больше не сбрасываются. Выставленные фильтры, порядок сортировки и размер страницы возвращаются такими же после перезагрузки, ухода в другой раздел и входа на следующий день — на каждой из четырёх вкладок свой набор. Вместе с отборами запоминается и выбранная очередь заявок («Требуют решения», «Срочные», «Ожидаются документы»): она, как и раньше, видна переключателем над таблицей"},
    {"kind":"improvement","text":"Выйти из своего набора можно одним нажатием: рядом с полосой фильтров появилась кнопка «Сбросить» — она видна, только когда есть что снимать, и снимает именно отборы, не трогая сортировку. На телефоне то же делает «Сбросить» в окне фильтров"},
    {"kind":"improvement","text":"Строка поиска не запоминается намеренно: набранный вчера серийный номер встретил бы вас утром пустым списком. Не запоминается и страница — список всегда открывается с первой: за ночь записи в нём меняются местами"},
    {"kind":"improvement","text":"Если сохранённый отбор указывает на то, чего в списке выбора больше нет — площадку закрыли, отдел выключили, подрядчика приостановили, — портал снимает такой отбор сам. Иначе список оказался бы пустым, а в поле стоял бы нечитаемый код"},
    {"kind":"improvement","text":"Набор хранится в браузере и привязан к учётной записи: за общим компьютером сменщик увидит свои отборы, а не ваши. Забытый набор портал удаляет сам через три месяца; в приватном режиме браузера отборы не сохраняются вовсе — список работает как прежде"}
  ]'::jsonb
);
